import numpy as np
from collections.abc import Sequence
from numbers import Real
from typing import Optional
from sklearn.base import BaseEstimator, ClusterMixin
from sklearn.utils.validation import check_array, check_is_fitted


class KMeans(ClusterMixin, BaseEstimator):
    def __init__(
        self,
        n_clusters: int,
        max_iter: int = 200,
        tol: Real = 1e-4,
        random_state: Optional[int] = None,
    ) -> None:
        self.n_clusters = n_clusters
        self.max_iter = max_iter
        self.tol = tol
        self.random_state = random_state

    def fit(
        self, X: Sequence[Sequence[Real]], y=None
    ) -> "KMeans":
        X = check_array(X)
        rng = np.random.default_rng(self.random_state)
        self.cluster_centers_ = self._random_centers(X, rng)
        for _ in range(self.max_iter):
            labels = self._assign(X)
            new_centers = self._update(X, labels, rng)
            if self._converged(new_centers, self.cluster_centers_):
                self.cluster_centers_ = new_centers
                break
            self.cluster_centers_ = new_centers
        self.labels_ = self._assign(X)
        self.n_features_in_ = X.shape[1]
        return self

    def predict(self, X: Sequence[Sequence[Real]]) -> np.ndarray:
        check_is_fitted(self, ["cluster_centers_"])
        X = check_array(X)
        return self._assign(X)

    def _random_centers(
        self, X: np.ndarray, rng: np.random.Generator
    ) -> np.ndarray:
        indices = rng.choice(len(X), self.n_clusters, replace=False)
        return X[indices].copy()

    def _assign(self, X: np.ndarray) -> np.ndarray:
        distances = np.sqrt(
            np.sum((X[:, None, :] - self.cluster_centers_[None, :, :]) ** 2, axis=2)
        )
        return np.argmin(distances, axis=1)

    def _update(
        self, X: np.ndarray, labels: np.ndarray, rng: np.random.Generator
    ) -> np.ndarray:
        new_centers = np.empty_like(self.cluster_centers_)
        for k in range(self.n_clusters):
            cluster_points = X[labels == k]
            if len(cluster_points) == 0:
                new_centers[k] = X[rng.integers(len(X))]
            else:
                new_centers[k] = cluster_points.mean(axis=0)
        return new_centers

    def _converged(
        self, new_centers: np.ndarray, old_centers: np.ndarray
    ) -> bool:
        return float(np.sum((new_centers - old_centers) ** 2)) < self.tol
