from numbers import Real


def human_duration(seconds: Real) -> str:
    """把秒数转成 1h 2m 3s 形式，负数按 0 处理，零秒返回 0s。"""
    total = max(int(round(float(seconds))), 0)
    parts: list[str] = []
    for unit, size in (('d', 86400), ('h', 3600), ('m', 60)):
        if total >= size:
            parts.append(f'{total // size}{unit}')
            total %= size
    if total or not parts:
        parts.append(f'{total}s')
    return ' '.join(parts)


if __name__ == '__main__':
    print(human_duration(3725))
    print(human_duration(-5))
