from collections.abc import Iterable, Sequence


def render_table(rows: Iterable[Sequence[str]]) -> str:
    """把二维文本渲染成等宽表格，各列左对齐，空输入返回空字符串。"""
    data = [[str(cell) for cell in row] for row in rows]
    if not data:
        return ''
    columns = max(len(row) for row in data)
    sizes = [0] * columns
    for row in data:
        for i, cell in enumerate(row):
            sizes[i] = max(sizes[i], len(cell))
    lines: list[str] = []
    for row in data:
        cells = [cell.ljust(sizes[i]) for i, cell in enumerate(row)]
        cells.extend([''] * (columns - len(cells)))
        lines.append(' | '.join(cells).rstrip())
    return chr(10).join(lines)


if __name__ == '__main__':
    print(render_table([['id', 'name'], ['1', 'alice']]))
