from collections.abc import Iterable, Mapping

CLOSERS = {')': '(', ']': '[', '}': '{'}


def brackets_balanced(chars: Iterable[str], pairs: Mapping[str, str] = CLOSERS) -> bool:
    """检查括号是否配对，遇到多余或错配的右括号立即返回 False。"""
    closers = dict(pairs)
    openers = set(closers.values())
    stack: list[str] = []
    for ch in chars:
        if ch in openers:
            stack.append(ch)
        elif ch in closers:
            if not stack or stack.pop() != closers[ch]:
                return False
    return not stack


if __name__ == '__main__':
    print(brackets_balanced('(a[b]{c})'))
    print(brackets_balanced('(]'))
```

