UNITS: dict[str, int] = {'s': 1, 'm': 60, 'h': 3600, 'd': 86400}
TOKEN = re.compile('([0-9]+(?:[.][0-9]+)?)([a-z]+)')


def parse_duration(text: str, units: Mapping[str, Integral] | None = None) -> int:
    """解析 1h30m 这类时长写法，无法解析返回 0 秒。"""
    table = UNITS if units is None else units
    pairs = TOKEN.findall(text.lower().replace(' ', ''))
    if not pairs:
        return 0
    total = 0.0
    for amount, unit in pairs:
        if unit not in table:
            return 0
        total += float(amount) * float(table[unit])
    return int(total)


if __name__ == '__main__':
    print(parse_duration('1h30m'))
```

