from numbers import Integral

PAIRS = (
    (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
    (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
    (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
)


def to_roman(number: Integral) -> str:
    """把 1 到 3999 的整数转成罗马数字，越界抛 ValueError。"""
    left = int(number)
    if not 0 < left < 4000:
        raise ValueError('number out of range')
    out: list[str] = []
    for value, symbol in PAIRS:
        while left >= value:
            out.append(symbol)
            left -= value
    return ''.join(out)


if __name__ == '__main__':
    print(to_roman(1994))
