import re
from collections.abc import Iterable

PATTERN = re.compile('[0-9]+ *x *[0-9]+')


def parse_size(text: str) -> tuple[int, int]:
    """解析 800x600 形式的尺寸，格式非法时返回 (0, 0)。"""
    match = PATTERN.fullmatch(text.strip().lower())
    if match is None:
        return (0, 0)
    width, height = match.group(0).replace(' ', '').split('x')
    return (int(width), int(height))


def parse_all(items: Iterable[str]) -> list[tuple[int, int]]:
    """批量解析尺寸，保持输入顺序。"""
    return [parse_size(item) for item in items]


