from collections.abc import Callable, Mapping


class LazyCache:
    """按需执行工厂函数并缓存结果的取值器。"""

    def __init__(self, factories: Mapping[str, Callable[[], object]]) -> None:
        self._factories = factories
        self._cache: dict[str, object] = {}

    def get(self, key: str) -> object:
        if key not in self._factories:
            raise KeyError(key)
        if key not in self._cache:
            self._cache[key] = self._factories[key]()
        return self._cache[key]


def lazy_cache(factories: Mapping[str, Callable[[], object]]) -> LazyCache:
    """把工厂映射包成按需计算的缓存对象。"""
    return LazyCache(factories)


if __name__ == '__main__':
    calls: list[str] = []
    cache = lazy_cache({'a': lambda: calls.append('a') or 1})
    print(cache.get('a'), cache.get('a'), calls)
