from collections.abc import Mapping


def merge(defaults: Mapping[str, object], override: Mapping[str, object]) -> dict[str, object]:
    """递归合并两层配置，override 优先；返回新对象，不修改入参。"""
    result: dict[str, object] = dict(defaults)
    for key, value in override.items():
        old = result.get(key)
        if isinstance(old, Mapping) and isinstance(value, Mapping):
            result[key] = merge(old, value)
        else:
            result[key] = value
    return result


if __name__ == '__main__':
