from collections.abc import Mapping
from numbers import Integral

IRREGULAR = {'child': 'children', 'person': 'people', 'man': 'men'}


def pluralize(word: str, count: Integral, irregular: Mapping[str, str] = IRREGULAR) -> str:
    """按数量返回单数或复数形式，不规则变化可以由映射覆盖。"""
    if int(count) == 1:
        return word
    table = dict(irregular)
    if word in table:
        return table[word]
    if word.endswith('y') and word[-2:-1] not in 'aeiou':
        return word[:-1] + 'ies'
    if word.endswith(('s', 'x', 'z', 'ch', 'sh')):
        return word + 'es'
    return word + 's'


