from collections.abc import Iterable, Mapping, Sequence
from numbers import Real


def sort_by_columns(rows: Iterable[Mapping[str, Real]], columns: Sequence[str]) -> list[dict[str, float]]:
    """按多个字段依次升序排序，字段缺失按 0 处理，返回新的 dict 列表。"""
